using V = std::vector<double>;
static double dot(const V& a, const V& b){ double s=0; for(size_t i=0;i<a.size();++i)s+=a[i]*b[i]; return s; }
int main(){
  std::vector<V> x={{2,2},{2,3},{3,2},{-2,-2},{-2,-3},{-3,-2}};
  std::vector<int> y={1,1,1,-1,-1,-1};
  std::vector<double> a(6,0.0); double beta=1.0; const double lr=0.001, limit=1e-5;
  bool converged=false;
  for(int epoch=0; epoch<200000; ++epoch){
    bool judge=false;
    for(int i=0;i<6;++i){
      double item1=0,item2=0;
      for(int j=0;j<6;++j){ item1+=a[j]*y[i]*y[j]*dot(x[i],x[j]); item2+=a[j]*y[i]*y[j]; }
      double delta=1.0-item1-beta*item2; a[i]+=lr*delta;
      if(a[i]<0) a[i]=0; else if(std::abs(delta)>limit) judge=true;
    }
    double item3=0; for(int i=0;i<6;++i)item3+=a[i]*y[i]; beta+=item3*item3/2.0;
    if(!judge){ converged=true; break; }
  }
  if(!converged) return 2;
  V w(2,0.0); double b=0; int ns=0;
  for(int i=0;i<6;++i) if(a[i]>1e-7){ ++ns; for(int d=0;d<2;++d)w[d]+=a[i]*y[i]*x[i][d]; }
  for(int i=0;i<6;++i) if(a[i]>1e-7)b+=y[i]-dot(w,x[i]); b/=ns;
  int correct=0; for(int i=0;i<6;++i) correct += ((dot(w,x[i])+b>=0?1:-1)==y[i]);
  if(correct!=6 || std::abs(w[0]-0.25)>1e-4 || std::abs(w[1]-0.25)>1e-4 || std::abs(b)>1e-4) return 3;
  std::cout<<"SVM PASS\n";
}

