#include <cmath>
#include <functional>
#include <iostream>
#include <memory>
#include <unordered_set>
#include <vector>
struct Value;
using P=std::shared_ptr<Value>;
struct Edge{P parent; double local;};
struct Value{
  double data,grad=0; std::vector<Edge> edges;
  explicit Value(double d):data(d){}
};
static P val(double x){return std::make_shared<Value>(x);}
static P add(const P&a,const P&b){auto o=val(a->data+b->data);o->edges={{a,1},{b,1}};return o;}
static P mul(const P&a,const P&b){auto o=val(a->data*b->data);o->edges={{a,b->data},{b,a->data}};return o;}
static void topo(const P&v,std::unordered_set<Value*>&seen,std::vector<P>&out){if(!seen.insert(v.get()).second)return;for(auto&e:v->edges)topo(e.parent,seen,out);out.push_back(v);}
static void backward(const P&y){std::unordered_set<Value*> seen;std::vector<P> order;topo(y,seen,order);for(auto&v:order)v->grad=0;y->grad=1;for(auto it=order.rbegin();it!=order.rend();++it)for(auto&e:(*it)->edges)e.parent->grad+=(*it)->grad*e.local;}
int main(){
  auto x1=val(2),x2=val(3),x3=val(5);
  auto y=add(mul(mul(mul(mul(x1,x1),x1),x2),x2),mul(x1,x3));
  backward(y);
  if(std::abs(y->data-82)>1e-12||std::abs(x1->grad-113)>1e-12||std::abs(x2->grad-48)>1e-12||std::abs(x3->grad-2)>1e-12)return 2;
  std::cout<<"LIGHTGRAD PASS\n";
}
